from messages import sanitize

def test_removed_fields():
    # Test that the function removes the specified keys
    msgs = [
        {'id': 1, 'output': 'out', 'model': 'm', 'meta': 'm', 'content': 'c'},
        {'id': 2, 'content': 'c2'},  # missing some fields
        {'a': 1},  # no removed keys
    ]
    result = sanitize(msgs)
    # For each result dict, none of the removed keys should be present
    for clean in result:
        for key in ('id', 'output', 'model', 'meta'):
            assert key not in clean, f"Key {key} still present in {clean}"
    # Also ensure that non-removed keys are present (if they existed)
    for i, clean in enumerate(result):
        if 'content' in msgs[i]:
            assert msgs[i]['content'] == clean.get('content'), "content mismatch"
    # For msg2, content should be preserved
    assert result[1].get('content') == msgs[1]['content'], "content not preserved for missing removed keys"

def test_preserves_original():
    # Original msgs should not be mutated
    msgs = [
        {'id': 1, 'output': 'out', 'model': 'm', 'meta': 'm', 'content': 'c'},
    ]
    original_copy = [dict(msg) for msg in msgs]  # deep copy
    result = sanitize(msgs)
    # Compare original msgs with original_copy after sanitization? Actually original msgs should remain same
    # Since sanitize uses dict(message) which creates a new dict, original msgs dict objects should not lose keys
    for i, msg in enumerate(msgs):
        for key in ('id', 'output', 'model', 'meta'):
            if key in msg:
                assert key in msg, f"Original key {key} removed from msgs[{i}]"
            # Also check that values equal
    # Simpler: compare msgs[i] with original_copy[i] after result (should be same as msgs because msgs not mutated)
    for i in range(len(msgs)):
        # msgs[i] is a dict, we can compare
        # We'll just check that msgs[i] still contains the removed keys if they existed
        if 'id' in msgs[i]:
            assert msgs[i]['id'] == msgs[i]['id']  # trivial
        # No mutation expected
    # More precise: check that msgs[0]['id'] still exists and same value
    assert msgs[0]['id'] == original_copy[0]['id']  # both same
    # Actually we need to ensure msgs dict wasn't modified by sanitize. Since sanitize creates a copy, it should be safe.
    # Let's assert that msgs[0] still has 'id'
    assert 'id' in msgs[0], "Original dict lost 'id'"

def test_preserves_content():
    # Non-removed field values should be exactly preserved
    msgs = [
        {'id': 1, 'output': 'out', 'model': 'm', 'meta': 'm', 'content': 'c', 'num': 42},
        {'id': 2, 'content': 'c2', 'extra': 'e'},
    ]
    result = sanitize(msgs)
    for i, clean in enumerate(result):
        # compare all non-removed keys
        for key in msgs[i]:
            if key not in ('id', 'output', 'model', 'meta'):
                assert msgs[i][key] == clean[key], f"Content mismatch for {key}: {msgs[i][key]} vs {clean.get(key)}"
    # Also ensure that if a key like 'id' exists, it's not present in clean (already tested)

if __name__ == '__main__':
    test_removed_fields()
    test_preserves_original()
    test_preserves_content()
    print('All tests passed')
